function stageOf(b){if(b.status==='success')return 3;if(b.scenario==='tests'&&b.status==='failed')return 1;if(b.scenario==='publish'&&b.status==='failed')return 3;return Math.min(3,sumStages.findIndex(n=>b.elapsed<n)<0?3:sumStages.findIndex(n=>b.elapsed<n));}
