function badge(status,label=''){const map={running:['Собирается','loader'],success:['Успешно','check'],failed:['Ошибка','x'],queued:['В очереди','clock'],cancelled:['Отменена','stop'],stale:['Нет свежих данных','alert'],ready:['На связи','check'],off:['Отключён','stop'],unverified:['Не проверен','clock'],checking:['Проверяется','loader']};const [text,name]=map[status]||[status,'info'];return `<span class="status ${status==='ready'?'success':status}">${icon(name,name==='loader'?'spin':'')}${esc(label||text)}</span>`;}
function btn(text,action,cls='',attrs=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;}
