function tabs(items,current,group){return `<div class="tabs" role="tablist" aria-label="${group}">${items.map(([id,text])=>`<button type="button" role="tab" id="tab-${group}-${id}" aria-controls="panel-${group}" aria-selected="${id===current}" data-tab-group="${group}" data-tab="${id}">${text}</button>`).join('')}</div>`;}
