function openServerDialog(id){const s=server(id);modalServerId=id||null;openDialog({title:s?'Настройки сервера':'Подключить сервер',description:'Сохраняется карточка с демоданными. SSH и сетевые подключения не выполняются.',kind:'server',submit:s?'Сохранить':'Добавить сервер',body:`<div class="fields">${field('Имя','name',s?.name||'','required maxlength="60" placeholder="builder-02"')}${field('IP или hostname','ip',s?.ip||'','required maxlength="100" placeholder="192.0.2.40"')}</div>${selectField('Назначение','role',[['apps','Приложения'],['worker','Сборки']],s?.role||'apps')}<div class="fields three">${field('CPU, vCPU','cpu',s?.cpu||4,'type="number" min="1" max="128" required')}${field('Память, GB','ram',s?.ram||8,'type="number" min="1" max="512" required')}${field('Диск, GB','disk',s?.disk||120,'type="number" min="10" max="20000" required')}</div>${field('Провайдер','provider',s?.provider||'Свой VDS','required maxlength="80"')}<div class="fields">${field('Стоимость','cost',s?.cost||'','maxlength="80" placeholder="18 € / мес"')}${field('Следующая оплата','payment',s?.payment||'','maxlength="60" placeholder="20 ноября"')}</div>`});}
