function openEnvDialog(id){const p=project(id);modalProjectId=id;openDialog({title:'Добавить окружение',description:'Свяжите приложение с целевым сервером.',kind:'environment',submit:'Добавить окружение',body:`${field('Имя','name',p.environments.some(e=>e.name==='development')?'staging':'development','required maxlength="40" pattern="[a-z][a-z0-9_-]*"')}${selectField('Сервер','server',D.servers.filter(s=>s.role==='apps').map(s=>[s.id,s.name]),'prod-01')}${field('Домен (необязательно)','domain','','maxlength="150" placeholder="app.example"')}`});}
